/**
 * Returns a stable string identifier for an extension instance.
 *
 * Uses `cardId` (the `extensible_cards` DB record ID as a string) when
 * available. Falls back to `appId` for preview-mode extensions that haven't
 * been deployed yet and therefore have no DB row. This fallback is safe for
 * logging, analytics, and proxy requests because those backends route by
 * `appId` (in the URL) and use `cardId` only for log correlation — not for
 * authorization or validation.
 *
 * For data resolution (`resolveData` RPC), use `resolveExtensionId()` in
 * `dataDependencyResolver.ts` instead, which returns `number | undefined`
 * and omits the field entirely when no ID is available.
 *
 * @ignore
 */
export function getExtensionIdentifier(contextData) {
    return contextData.cardId ?? contextData.appId.toString();
}
